/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
from retry import retry

for path in Path('.').glob('*.py'):
    compile(path.read_text(), str(path), 'exec')

for budget in range(1, 9):
    for successful_attempt in range(1, budget + 1):
        calls = []
        expected = object()
        def succeeds():
            calls.append(1)
            if len(calls) < successful_attempt:
                raise ConnectionError('transient')
            return expected
        assert retry(succeeds, budget) is expected
        assert len(calls) == successful_attempt

    calls = []
    failures = []
    def fails():
        calls.append(1)
        error = ConnectionError(f'attempt {len(calls)}')
        failures.append(error)
        raise error
    try:
        retry(fails, budget)
    except ConnectionError as error:
        assert len(calls) == budget
        assert error is failures[-1]
    else:
        raise AssertionError('Final error was swallowed')

    for error in (RuntimeError('permanent'), ValueError('invalid'), KeyboardInterrupt()):
        calls = []
        def permanent():
            calls.append(1)
            raise error
        try:
            retry(permanent, budget)
        except BaseException as caught:
            assert caught is error
            assert len(calls) == 1
        else:
            raise AssertionError('Non-transient error was swallowed')

    calls = []
    assert retry(lambda: calls.append(1), budget) is None
    assert len(calls) == 1

for budget in (-5, -1, 0):
    calls = []
    try:
        retry(lambda: calls.append(1), budget)
    except ValueError:
        assert calls == []
    else:
        raise AssertionError('Invalid budget was accepted')

print('PASS: compile checks; budgets 1–8; every success position; exact exhaustion and final error identity; other errors; None success; nonpositive budgets')
PY"

